// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address target = address(0x5678);
        uint256 value = 1 wei;
        bytes memory data = "";
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call{value: 1 wei}("");
        require(ok);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        bool reverted = false;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true && address(c).balance == balanceBefore);
    }
}
